<?php
declare(strict_types=1);
const SV_NEXT_CYCLE_CONTRACT='2026-10-25-non-destructive-next-cycle-r1';
function sv_next_cycle_create(PDO $pdo,array $campaign,array $version,string $actor):array {
    $sourceCampaignId=(int)$campaign['id'];$sourceVersionId=(int)$version['id'];$liveVersionId=(int)$campaign['CurrentVersionID'];$confirmation='CREATE NEXT CYCLE '.$campaign['CampaignCode'].' V'.$version['VersionNo'];
    $existing=db_row('SELECT TargetCampaignID,TargetVersionID FROM SafetyVote_CampaignVersionLineage WHERE SourceCampaignID=? AND SourceVersionID=? FOR UPDATE',[$sourceCampaignId,$sourceVersionId]);if($existing)throw new RuntimeException('NEXT_CYCLE_ALREADY_CREATED');
    $year=(int)(new DateTimeImmutable('now',new DateTimeZone('Asia/Bangkok')))->format('Y');$last=db_row('SELECT MAX(CAST(SUBSTRING(CampaignCode,5,3) AS UNSIGNED)) sequenceNo FROM SafetyVote_Campaigns WHERE CampaignCode REGEXP ? FOR UPDATE',['^SHE-[0-9]{3}-'.$year.'$']);$code=sv_campaign_code((int)($last['sequenceNo']??0)+1,$year);if(!$code)throw new RuntimeException('CAMPAIGN_CODE_EXHAUSTED');
    $stmt=$pdo->prepare("INSERT INTO SafetyVote_Campaigns(CampaignCode,Status,OwnerEmployeeID,DiscoveryMode,ScheduledOpenAt,ScheduledCloseAt,CreatedBy,UpdatedBy) VALUES(?,'Draft',?,?,?,?,?,?)");$stmt->execute([$code,$campaign['OwnerEmployeeID']?:$actor,$campaign['DiscoveryMode']?:'public_listing',$version['OpenAt'],$version['CloseAt'],$actor,$actor]);$targetCampaignId=(int)$pdo->lastInsertId();
    $stmt=$pdo->prepare("INSERT INTO SafetyVote_CampaignVersions(CampaignID,ParentVersionID,ChangeReason,VersionNo,ContractVersion,TemplateKey,CampaignType,PrivacyMode,TitleTh,TitleEn,Summary,Description,RulesText,TimeZone,OpenAt,CloseAt,ResultVisibility,OfficialResultTopN,ResultReleasePolicy,MaxParticipationAttempts,LiveLeaderboardEnabled,LiveLeaderboardTopN,LiveLeaderboardScoreMode,LiveLeaderboardVisibility,LiveLeaderboardRefreshSeconds,LiveLeaderboardPrivacyThreshold,EditPolicy,ScoringMethod,ScoringConfigJson,TieBreakRule,QuorumRuleJson,PrivacyThreshold,AllowAbstain,RandomizeOptions,Status,CreatedBy,UpdatedBy) SELECT ?,id,CONCAT('Non-destructive next cycle from ',?),VersionNo,ContractVersion,TemplateKey,CampaignType,PrivacyMode,TitleTh,TitleEn,Summary,Description,RulesText,TimeZone,OpenAt,CloseAt,ResultVisibility,OfficialResultTopN,ResultReleasePolicy,MaxParticipationAttempts,LiveLeaderboardEnabled,LiveLeaderboardTopN,LiveLeaderboardScoreMode,LiveLeaderboardVisibility,LiveLeaderboardRefreshSeconds,LiveLeaderboardPrivacyThreshold,'revision_required',ScoringMethod,ScoringConfigJson,TieBreakRule,QuorumRuleJson,PrivacyThreshold,AllowAbstain,RandomizeOptions,'Draft',?,? FROM SafetyVote_CampaignVersions WHERE id=?");$stmt->execute([$targetCampaignId,$campaign['CampaignCode'],$actor,$actor,$sourceVersionId]);$targetVersionId=(int)$pdo->lastInsertId();
    $pdo->prepare('UPDATE SafetyVote_Campaigns SET CurrentVersionID=? WHERE id=?')->execute([$targetVersionId,$targetCampaignId]);
    $pdo->prepare("INSERT INTO SafetyVote_Stages(CampaignVersionID,StageKey,StageName,StageType,SequenceNo,OpenAt,CloseAt,AdvanceRuleJson,ResultVisibility,Status,CreatedBy,UpdatedBy) SELECT ?,StageKey,StageName,StageType,SequenceNo,OpenAt,CloseAt,AdvanceRuleJson,ResultVisibility,'Draft',?,? FROM SafetyVote_Stages WHERE CampaignVersionID=?")->execute([$targetVersionId,$actor,$actor,$sourceVersionId]);
    $pdo->prepare('INSERT INTO SafetyVote_EligibilityRules(CampaignVersionID,RuleGroup,RuleOrder,Effect,AttributeKey,Operator,ValuesJson,Reason,IsActive,CreatedBy,UpdatedBy) SELECT ?,RuleGroup,RuleOrder,Effect,AttributeKey,Operator,ValuesJson,Reason,IsActive,?,? FROM SafetyVote_EligibilityRules WHERE CampaignVersionID=?')->execute([$targetVersionId,$actor,$actor,$sourceVersionId]);
    $pdo->prepare("INSERT INTO SafetyVote_Questions(CampaignVersionID,QuestionCode,QuestionType,Title,HelpText,ImageFileID,ImageAltText,IsRequired,MinSelections,MaxSelections,RandomizeOptions,AllowComment,ValidationJson,DisplayConditionJson,ResultVisibility,SortOrder,Status,CreatedBy,UpdatedBy) SELECT ?,QuestionCode,QuestionType,Title,HelpText,NULL,NULL,IsRequired,MinSelections,MaxSelections,RandomizeOptions,AllowComment,ValidationJson,DisplayConditionJson,ResultVisibility,SortOrder,Status,?,? FROM SafetyVote_Questions WHERE CampaignVersionID=?")->execute([$targetVersionId,$actor,$actor,$sourceVersionId]);
    $pdo->prepare("INSERT INTO SafetyVote_Options(QuestionID,OptionCode,Label,Description,ScoreValue,IsAbstain,FileID,SortOrder,Status,CreatedBy,UpdatedBy) SELECT tq.id,so.OptionCode,so.Label,so.Description,so.ScoreValue,so.IsAbstain,NULL,so.SortOrder,so.Status,?,? FROM SafetyVote_Options so JOIN SafetyVote_Questions sq ON sq.id=so.QuestionID JOIN SafetyVote_Questions tq ON tq.CampaignVersionID=? AND tq.QuestionCode=sq.QuestionCode WHERE sq.CampaignVersionID=?")->execute([$actor,$actor,$targetVersionId,$sourceVersionId]);
    $result=db_row("SELECT ResultHash FROM SafetyVote_ResultSnapshots WHERE CampaignVersionID=? AND Status IN ('Published','Certified','Frozen') ORDER BY SnapshotNo DESC,id DESC LIMIT 1",[$liveVersionId]);$pdo->prepare('INSERT INTO SafetyVote_CampaignVersionLineage(SourceCampaignID,SourceVersionID,TargetCampaignID,TargetVersionID,SourceResultHash,ConfirmationHash,CreatedBy) VALUES(?,?,?,?,?,SHA2(?,256),?)')->execute([$sourceCampaignId,$sourceVersionId,$targetCampaignId,$targetVersionId,$result['ResultHash']??null,$confirmation,$actor]);
    return['contract'=>SV_NEXT_CYCLE_CONTRACT,'sourceCampaignId'=>$sourceCampaignId,'sourceLiveVersionId'=>$liveVersionId,'sourceDraftVersionId'=>$sourceVersionId,'targetCampaignId'=>$targetCampaignId,'targetVersionId'=>$targetVersionId,'targetCampaignCode'=>$code,'status'=>'Draft','sourceCampaignPreserved'=>true,'sourceResultHashPreserved'=>true,'requiresFreshReadiness'=>true,'requiresFreshEligibilityFreeze'=>true,'requiresPrivateImageReupload'=>true];
}
